'use client';

import {
  AuthProvider,
  OpenfortProvider,
  RecoveryMethod,
} from '@openfort/react';
import { getDefaultConfig, OpenfortWagmiBridge } from '@openfort/react/wagmi';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import type { ReactNode } from 'react';
import { base, baseSepolia } from 'viem/chains';
import { createConfig, WagmiProvider } from 'wagmi';
import { AuthSessionProvider } from '@/components/auth/auth-session-provider';

const publishableKey = process.env.NEXT_PUBLIC_OPENFORT_PUBLIC_KEY;
const shieldPublishableKey = process.env.NEXT_PUBLIC_SHIELD_API_KEY;
const walletConnectProjectId =
  process.env.NEXT_PUBLIC_WALLET_CONNECT_PROJECT_ID || undefined;
const supportedChains = [base, baseSepolia] as const;
const defaultChainId =
  process.env.NEXT_PUBLIC_ENVIRONMENT === 'production'
    ? base.id
    : baseSepolia.id;

const queryClient = new QueryClient();
const wagmiConfig = createConfig(
  getDefaultConfig({
    appName: 'InfraFund',
    chains: supportedChains,
    ssr: true,
    walletConnectProjectId,
  })
);

async function getEncryptionSession({
  accessToken,
  otpCode,
  userId,
}: {
  accessToken: string;
  otpCode?: string;
  userId: string;
}) {
  const response = await fetch('/api/auth/encryption-session', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ otp_code: otpCode, user_id: userId }),
  });
  const data: unknown = await response.json().catch(() => null);

  if (!response.ok) {
    const message =
      data && typeof data === 'object' && 'message' in data
        ? String(data.message)
        : 'Failed to create encryption session.';
    throw new Error(message);
  }

  if (
    !data ||
    typeof data !== 'object' ||
    !('session' in data) ||
    typeof data.session !== 'string'
  ) {
    throw new Error('Invalid encryption session response.');
  }

  return data.session;
}

function OpenfortNotConfigured() {
  return (
    <div className="rounded-lg border border-yellow-500 bg-yellow-900/20 p-4 text-left text-sm text-yellow-100 max-w-md mx-auto mt-10">
      <p className="font-semibold">Openfort is not configured.</p>
      <p className="mt-2">
        Add <code>NEXT_PUBLIC_OPENFORT_PUBLIC_KEY</code> and{' '}
        <code>NEXT_PUBLIC_SHIELD_API_KEY</code> to your <code>.env.local</code>{' '}
        file.
      </p>
    </div>
  );
}

export function AppProviders({ children }: { children: ReactNode }) {
  if (!publishableKey || !shieldPublishableKey) {
    return (
      <QueryClientProvider client={queryClient}>
        <OpenfortNotConfigured />
      </QueryClientProvider>
    );
  }

  return (
    <QueryClientProvider client={queryClient}>
      <WagmiProvider config={wagmiConfig}>
        <OpenfortWagmiBridge>
          <OpenfortProvider
            publishableKey={publishableKey}
            walletConfig={{
              shieldPublishableKey,
              ethereum: {
                chainId: defaultChainId,
                ethereumFeeSponsorshipId:
                  process.env.NEXT_PUBLIC_POLICY_ID || undefined,
              },
              connectOnLogin: false,
              getEncryptionSession,
            }}
            uiConfig={{
              theme: 'midnight',
              mode: 'dark',
              authProviders: [AuthProvider.GOOGLE, AuthProvider.EMAIL_OTP],
              walletRecovery: { defaultMethod: RecoveryMethod.AUTOMATIC },
            }}
          >
            <AuthSessionProvider>{children}</AuthSessionProvider>
          </OpenfortProvider>
        </OpenfortWagmiBridge>
      </WagmiProvider>
    </QueryClientProvider>
  );
}

'use client';

import type { User } from '@openfort/openfort-js';
import { RecoveryMethod, useSignOut, useUI, useUser } from '@openfort/react';
import { useEthereumEmbeddedWallet } from '@openfort/react/ethereum';
import {
  checkOpenfortUser,
  deleteBackendAccount,
  exchangeOpenfortSession,
  getBackendMe,
  logoutBackendSession,
  refreshBackendSession,
  type BackendMeResponse,
} from '@/lib/backend-auth-client';
import {
  QualificationQuestionnaire,
  type QualificationSubmission,
} from './qualification-questionnaire';
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { usePathname } from 'next/navigation';
import { reportError } from '@/lib/error-reporting';

type AppSessionStatus =
  | 'idle'
  | 'loading'
  | 'needs_onboarding'
  | 'creating_wallet'
  | 'authenticated'
  | 'unauthenticated'
  | 'error';

type ErrorCategory = 'recoverable' | 'fatal';

interface AuthSessionContextValue {
  status: AppSessionStatus;
  backendAccessToken: string | null;
  backendUser: BackendMeResponse | null;
  openfortUser: User | null;
  isOpenfortLoading: boolean;
  isOpenfortAuthenticated: boolean;
  error: string | null;
  errorCategory: ErrorCategory | null;
  retry: () => void;
  deleteAccount: () => Promise<void>;
}

const AuthSessionContext = createContext<AuthSessionContextValue | null>(null);
const ONBOARDING_STORAGE_KEY = 'infrafund:onboarding-draft';

function getErrorMessage(error: unknown) {
  if (error instanceof Error && error.message) {
    return error.message;
  }

  return 'Failed to initialize your session.';
}

function getUserFacingErrorMessage(message: string) {
  if (/failed to establish iFrame connection/i.test(message)) {
    return "We couldn't connect to the wallet service. Please check your connection and try again.";
  }

  if (/not logged in|session/i.test(message)) {
    return 'Your session expired. Please sign in again.';
  }

  if (/failed to fetch|networkerror/i.test(message)) {
    return 'We hit a network issue. Please try again.';
  }

  return 'Something went wrong. Please try again.';
}

function classifyError(message: string): ErrorCategory {
  if (
    /failed to fetch|networkerror|failed to establish iframe|timeout|temporarily|try again/i.test(
      message
    )
  ) {
    return 'recoverable';
  }

  return 'fatal';
}

function clearOnboardingDraft() {
  if (typeof window !== 'undefined') {
    window.sessionStorage.removeItem(ONBOARDING_STORAGE_KEY);
  }
}

export function AuthSessionProvider({ children }: { children: ReactNode }) {
  const { user, isLoading, isAuthenticated, getAccessToken } = useUser();
  const { signOut } = useSignOut();
  const { close: closeOpenfortModal } = useUI();
  const { create, wallets } = useEthereumEmbeddedWallet();
  const openfortUserId = user?.id ?? null;
  const [status, setStatus] = useState<AppSessionStatus>('idle');
  const [backendAccessToken, setBackendAccessToken] = useState<string | null>(
    null
  );
  const [backendUser, setBackendUser] = useState<BackendMeResponse | null>(
    null
  );
  const [error, setError] = useState<string | null>(null);
  const [errorCategory, setErrorCategory] = useState<ErrorCategory | null>(
    null
  );
  const [retryCount, setRetryCount] = useState(0);
  const pathname = usePathname();
  const [pendingOnboardingAccessToken, setPendingOnboardingAccessToken] =
    useState<string | null>(null);
  const [pendingWalletCreation, setPendingWalletCreation] = useState<{
    accessToken: string;
    user: BackendMeResponse;
  } | null>(null);
  const previousAuthState = useRef(false);
  const bootstrapAttemptKeyRef = useRef<string | null>(null);

  const clearSession = useCallback(() => {
    setBackendAccessToken(null);
    setBackendUser(null);
    setPendingOnboardingAccessToken(null);
    setPendingWalletCreation(null);
    setError(null);
    setErrorCategory(null);
    bootstrapAttemptKeyRef.current = null;
    clearOnboardingDraft();
  }, []);

  const commitUserFacingError = useCallback((raw: string) => {
    const userMessage = getUserFacingErrorMessage(raw);
    setError(userMessage);
    setErrorCategory(classifyError(raw));
    return userMessage;
  }, []);

  const baseReportExtras = useCallback(
    () => ({
      route: pathname ?? null,
      retryCount,
      openfortUserId: openfortUserId ? openfortUserId.slice(-6) : null,
    }),
    [openfortUserId, pathname, retryCount]
  );

  const finalizeAuthenticatedSession = useCallback(
    (accessToken: string, currentUser: BackendMeResponse) => {
      closeOpenfortModal();
      setBackendAccessToken(accessToken);
      setBackendUser(currentUser);
      setPendingOnboardingAccessToken(null);
      setPendingWalletCreation(null);
      setError(null);
      setErrorCategory(null);
      clearOnboardingDraft();
      setStatus('authenticated');
    },
    [closeOpenfortModal]
  );

  const createWalletIfNeeded = useCallback(
    async (accessToken: string, currentUser: BackendMeResponse) => {
      setBackendAccessToken(accessToken);
      setBackendUser(currentUser);
      setPendingWalletCreation({ accessToken, user: currentUser });

      if (wallets.length > 0) {
        finalizeAuthenticatedSession(accessToken, currentUser);
        return;
      }

      setStatus('creating_wallet');

      try {
        await create({
          recoveryMethod: RecoveryMethod.AUTOMATIC,
        });
        finalizeAuthenticatedSession(accessToken, currentUser);
      } catch (walletError) {
        const rawMessage = getErrorMessage(walletError);
        reportError(walletError, {
          area: 'wallet',
          tags: { stage: 'create' },
          extra: {
            ...baseReportExtras(),
            hasExistingWallet: wallets.length > 0,
          },
        });
        commitUserFacingError(rawMessage);
        setStatus('error');
      }
    },
    [
      baseReportExtras,
      commitUserFacingError,
      create,
      finalizeAuthenticatedSession,
      wallets.length,
    ]
  );

  const bootstrapSession = useCallback(async () => {
    if (!openfortUserId) {
      clearSession();
      setStatus('unauthenticated');
      return;
    }

    setStatus('loading');
    setError(null);

    try {
      const refreshedSession = await refreshBackendSession().catch(() => null);

      if (refreshedSession) {
        try {
          const me = await getBackendMe(refreshedSession.access_token);
          finalizeAuthenticatedSession(refreshedSession.access_token, me);
          return;
        } catch {
          // Refresh token was valid but user is inaccessible (e.g. soft-deleted).
          // Clear the stale cookie and fall through to Openfort re-auth.
          await logoutBackendSession().catch(() => undefined);
        }
      }

      const openfortAccessToken = await getAccessToken();

      if (!openfortAccessToken) {
        throw new Error('Openfort access token is unavailable.');
      }

      const checkResponse = await checkOpenfortUser(openfortAccessToken);

      if (!checkResponse.exists) {
        closeOpenfortModal();
        setPendingOnboardingAccessToken(openfortAccessToken);
        setStatus('needs_onboarding');
        return;
      }

      const loginResponse = await exchangeOpenfortSession(openfortAccessToken);
      const me = await getBackendMe(loginResponse.access_token);

      finalizeAuthenticatedSession(loginResponse.access_token, me);
    } catch (sessionError) {
      reportError(sessionError, {
        area: 'auth',
        tags: { stage: 'bootstrap' },
        extra: baseReportExtras(),
      });
      setBackendAccessToken(null);
      setBackendUser(null);
      setPendingOnboardingAccessToken(null);
      setPendingWalletCreation(null);
      commitUserFacingError(getErrorMessage(sessionError));
      setStatus('error');
    }
  }, [
    baseReportExtras,
    clearSession,
    closeOpenfortModal,
    commitUserFacingError,
    finalizeAuthenticatedSession,
    getAccessToken,
    openfortUserId,
  ]);

  const completeOnboarding = useCallback(
    async ({ role, type, organizationName }: QualificationSubmission) => {
      if (!pendingOnboardingAccessToken) {
        setError('Openfort access token is unavailable.');
        setStatus('error');
        return;
      }

      setStatus('loading');
      setError(null);

      try {
        const loginResponse = await exchangeOpenfortSession(
          pendingOnboardingAccessToken,
          {
            role,
            type,
            organization_name:
              type === 'organization' ? organizationName?.trim() : undefined,
          }
        );
        const me = await getBackendMe(loginResponse.access_token);

        await createWalletIfNeeded(loginResponse.access_token, me);
      } catch (sessionError) {
        reportError(sessionError, {
          area: 'auth',
          tags: { stage: 'onboarding' },
          extra: baseReportExtras(),
        });
        commitUserFacingError(getErrorMessage(sessionError));
        setStatus('needs_onboarding');
      }
    },
    [
      baseReportExtras,
      commitUserFacingError,
      createWalletIfNeeded,
      pendingOnboardingAccessToken,
    ]
  );

  const abandonOnboarding = useCallback(async () => {
    clearSession();
    setStatus('loading');

    await Promise.allSettled([
      logoutBackendSession(),
      signOut().catch(() => undefined),
    ]);

    clearSession();
    setStatus('unauthenticated');
  }, [clearSession, signOut]);

  const deleteAccount = useCallback(async () => {
    setStatus('loading');
    setError(null);

    try {
      if (backendAccessToken) {
        await deleteBackendAccount(backendAccessToken);
      }
    } catch (deleteError) {
      reportError(deleteError, {
        area: 'auth',
        tags: { stage: 'delete-account' },
        extra: baseReportExtras(),
      });
      commitUserFacingError(getErrorMessage(deleteError));
      setStatus('authenticated');
      return;
    }

    await Promise.allSettled([
      logoutBackendSession().catch(() => undefined),
      signOut().catch(() => undefined),
    ]);

    clearSession();
    setStatus('unauthenticated');
  }, [
    backendAccessToken,
    baseReportExtras,
    clearSession,
    commitUserFacingError,
    signOut,
  ]);

  const retry = useCallback(() => {
    if (pendingWalletCreation) {
      void createWalletIfNeeded(
        pendingWalletCreation.accessToken,
        pendingWalletCreation.user
      );
      return;
    }

    setRetryCount((count) => count + 1);
  }, [createWalletIfNeeded, pendingWalletCreation]);

  useEffect(() => {
    if (isLoading) {
      setStatus((currentStatus) =>
        currentStatus === 'authenticated' ||
        currentStatus === 'needs_onboarding'
          ? currentStatus
          : 'loading'
      );
      return;
    }

    if (!isAuthenticated || !openfortUserId) {
      clearSession();
      setStatus('unauthenticated');
      return;
    }

    const bootstrapAttemptKey = `${openfortUserId}:${retryCount}`;

    if (bootstrapAttemptKeyRef.current === bootstrapAttemptKey) {
      return;
    }

    bootstrapAttemptKeyRef.current = bootstrapAttemptKey;

    void bootstrapSession();
  }, [
    bootstrapSession,
    clearSession,
    isAuthenticated,
    isLoading,
    openfortUserId,
    retryCount,
  ]);

  useEffect(() => {
    const signedOut =
      previousAuthState.current && !isLoading && !isAuthenticated;

    previousAuthState.current = isAuthenticated;

    if (!signedOut) {
      return;
    }

    clearSession();
    setStatus('unauthenticated');
    void logoutBackendSession().catch(() => undefined);
  }, [clearSession, isAuthenticated, isLoading]);

  const value = useMemo<AuthSessionContextValue>(
    () => ({
      status,
      backendAccessToken,
      backendUser,
      openfortUser: user,
      isOpenfortLoading: isLoading,
      isOpenfortAuthenticated: isAuthenticated,
      error,
      errorCategory,
      retry,
      deleteAccount,
    }),
    [
      status,
      backendAccessToken,
      backendUser,
      user,
      isLoading,
      isAuthenticated,
      error,
      errorCategory,
      retry,
      deleteAccount,
    ]
  );

  return (
    <AuthSessionContext.Provider value={value}>
      {children}
      <QualificationQuestionnaire
        isOpen={status === 'needs_onboarding'}
        openfortUser={user}
        submitError={error}
        isSubmitting={status === 'loading'}
        onClose={() => {
          void abandonOnboarding();
        }}
        onSubmit={completeOnboarding}
        onDisqualifiedSuccess={abandonOnboarding}
      />
    </AuthSessionContext.Provider>
  );
}

export function useAuthSession() {
  const context = useContext(AuthSessionContext);

  if (!context) {
    throw new Error(
      'useAuthSession must be used within an AuthSessionProvider.'
    );
  }

  return context;
}

import 'server-only';

import Openfort from '@openfort/openfort-node';

import { ApiError } from '@/server/http';
import { logger } from '@/server/logger';
import { requireServerEnv } from '@/server/env';

export interface VerifiedOpenfortSession {
  user: {
    id: string;
    email?: string | null;
    name?: string | null;
    phoneNumber?: string | null;
  };
  session: {
    id?: string | null;
    expiresAt?: string | null;
  };
}

let cachedClient: Openfort | undefined;

function getOpenfortClient() {
  if (cachedClient) return cachedClient;

  const { openfort } = requireServerEnv(['openfort']);
  cachedClient = new Openfort(openfort.secretKey!, {
    basePath: openfort.baseUrl,
    publishableKey: openfort.publishableKey,
  });

  return cachedClient;
}

function normalizeOpenfortSession(session: unknown): VerifiedOpenfortSession {
  if (!session || typeof session !== 'object') {
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }

  const value = session as {
    user?: {
      id?: unknown;
      email?: unknown;
      name?: unknown;
      phoneNumber?: unknown;
    };
    session?: {
      id?: unknown;
      expiresAt?: unknown;
    };
  };
  const userId = value.user?.id;

  if (typeof userId !== 'string' || !userId.trim()) {
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }

  return {
    user: {
      id: userId,
      email:
        typeof value.user?.email === 'string' ? value.user.email : undefined,
      name: typeof value.user?.name === 'string' ? value.user.name : undefined,
      phoneNumber:
        typeof value.user?.phoneNumber === 'string'
          ? value.user.phoneNumber
          : undefined,
    },
    session: {
      id: typeof value.session?.id === 'string' ? value.session.id : undefined,
      expiresAt:
        typeof value.session?.expiresAt === 'string'
          ? value.session.expiresAt
          : undefined,
    },
  };
}

export async function verifyOpenfortAccessToken(accessToken: string) {
  try {
    const session = await getOpenfortClient().iam.getSession({ accessToken });
    return normalizeOpenfortSession(session);
  } catch (error) {
    if (error instanceof ApiError) throw error;

    logger.warn({ err: error }, 'Openfort session verification failed');
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }
}

export function deleteOpenfortUser(openfortUserId: string) {
  return getOpenfortClient().iam.users.delete(openfortUserId);
}

export function createOpenfortEncryptionSession() {
  const { shield } = requireServerEnv(['shield']);

  return getOpenfortClient().createEncryptionSession(
    shield.publishableKey!,
    shield.secretKey!,
    shield.encryptionShare!,
    shield.url
  );
}

'use client';

interface BackendLoginResponse {
  user_id: string;
  access_token: string;
  expires_at: string;
}

interface BackendCheckResponse {
  exists: boolean;
}

interface BackendCountriesResponse {
  items: BackendCountryRecord[];
}

interface BackendCountryRecord {
  ID: number;
  Name: string;
  Iso: string;
  Iso3: string;
  Code: number;
  PhoneCode: number;
}

export interface CountryOption {
  id: number;
  name: string;
  iso?: string;
  iso3?: string;
  code?: number;
  phoneCode?: number;
}

interface OpenfortExchangePayload {
  first_name?: string;
  last_name?: string;
  organization_name?: string;
  phone_number?: string;
  email?: string;
  type?: 'individual' | 'organization';
  role?: string;
}

interface NonResidentIndividualPayload {
  first_name: string;
  last_name: string;
  email: string;
  country_id: number;
}

interface NonResidentCompanyPayload {
  first_name: string;
  last_name: string;
  company_name: string;
  email: string;
  country_id: number;
}

export interface BackendMeResponse {
  user_id: string;
  openfort_user_id: string;
  email: string | null;
  first_name: string | null;
  last_name: string | null;
  company_name: string | null;
  phone_number: string | null;
  type: string;
  role: string;
  status: string;
  kyc_verified: boolean;
  kyb_verified: boolean;
}

interface SuccessResponse<T> {
  code: string;
  data: T;
}

interface ErrorResponse {
  message?: string;
  detail?: string;
}

function buildUrl(path: string) {
  const normalizedPath = path.replace(/^\/+/, '');

  return `/api/v1/${normalizedPath}`;
}

async function request<T>(
  path: string,
  init: RequestInit & { accessToken?: string } = {}
) {
  const headers = new Headers(init.headers);

  if (init.body && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json');
  }

  if (init.accessToken) {
    headers.set('Authorization', `Bearer ${init.accessToken}`);
  }

  const response = await fetch(buildUrl(path), {
    ...init,
    headers,
    credentials: 'include',
  });

  if (!response.ok) {
    let message = 'Request failed';

    try {
      const errorBody = (await response.json()) as ErrorResponse;
      message = errorBody.message || errorBody.detail || message;
    } catch {}

    throw new Error(message);
  }

  if (response.status === 204) {
    return null as T;
  }

  const body = (await response.json()) as SuccessResponse<T>;
  return body.data;
}

function normalizeCountry(country: BackendCountryRecord): CountryOption {
  return {
    id: country.ID,
    name: country.Name,
    iso: country.Iso,
    iso3: country.Iso3,
    code: country.Code,
    phoneCode: country.PhoneCode,
  };
}

export async function checkOpenfortUser(openfortAccessToken: string) {
  return request<BackendCheckResponse>('auth/openfort/check', {
    method: 'GET',
    accessToken: openfortAccessToken,
  });
}

export async function exchangeOpenfortSession(
  openfortAccessToken: string,
  body: OpenfortExchangePayload = {}
) {
  return request<BackendLoginResponse>('auth/openfort/exchange', {
    method: 'POST',
    accessToken: openfortAccessToken,
    body: JSON.stringify(body),
  });
}

export async function refreshBackendSession() {
  return request<BackendLoginResponse>('auth/refresh', {
    method: 'POST',
  });
}

export async function getBackendMe(accessToken: string) {
  return request<BackendMeResponse>('me', {
    method: 'GET',
    accessToken,
  });
}

export async function getCountries() {
  const response = await request<BackendCountriesResponse>(
    'locations/countries',
    {
      method: 'GET',
    }
  );

  return response.items
    .map(normalizeCountry)
    .filter((country) => country.id > 0 && country.name);
}

export async function submitNonResidentIndividual(
  payload: NonResidentIndividualPayload,
  captchaToken: string
) {
  await request<null>('non-resident-waitlist/individual', {
    method: 'POST',
    headers: {
      'X-Captcha-Token': captchaToken,
    },
    body: JSON.stringify(payload),
  });
}

export async function submitNonResidentCompany(
  payload: NonResidentCompanyPayload,
  captchaToken: string
) {
  await request<null>('non-resident-waitlist/company', {
    method: 'POST',
    headers: {
      'X-Captcha-Token': captchaToken,
    },
    body: JSON.stringify(payload),
  });
}

export async function logoutBackendSession() {
  await request<null>('auth/logout', {
    method: 'POST',
  });
}

export async function deleteBackendAccount(accessToken: string) {
  await request<null>('me', {
    method: 'DELETE',
    accessToken,
  });
}

import { NextRequest, NextResponse } from 'next/server';

import { requireBearerToken } from '@/server/auth/http';
import { ApiError, handleApiError } from '@/server/http';
import { logger } from '@/server/logger';
import {
  createOpenfortEncryptionSession,
  verifyOpenfortAccessToken,
} from '@/server/openfort/session';

export async function POST(request: NextRequest) {
  try {
    const accessToken = requireBearerToken(request);
    const body = await request.json().catch(() => ({}));
    const requestedUserId =
      body && typeof body === 'object' && 'user_id' in body
        ? body.user_id
        : undefined;

    if (typeof requestedUserId !== 'string' || !requestedUserId.trim()) {
      throw new ApiError('BAD_REQUEST', 'Openfort user ID is required.');
    }

    const session = await verifyOpenfortAccessToken(accessToken);

    if (session.user.id !== requestedUserId) {
      throw new ApiError(
        'FORBIDDEN',
        'Openfort user mismatch for encryption session.'
      );
    }

    const encryptionSession = await createOpenfortEncryptionSession();

    return NextResponse.json({ session: encryptionSession });
  } catch (err) {
    logger.error({ err }, 'Encryption session error');
    return handleApiError(err);
  }
}

