   3: import { NextResponse } from 'next/server';
   4: 
   5: export type ApiErrorCode =
   6:   | 'BAD_REQUEST'
   7:   | 'UNAUTHORIZED'
   8:   | 'FORBIDDEN'
   9:   | 'NOT_FOUND'
  10:   | 'CONFLICT'
  11:   | 'TOO_MANY_REQUESTS'
  12:   | 'VALIDATION_ERROR'
  13:   | 'INTERNAL_SERVER_ERROR'
  14:   | 'SERVICE_UNAVAILABLE';
  15: 
  16: export interface ApiErrorBody {
  17:   code: ApiErrorCode;
  18:   message: string;
  19:   detail?: string;
  20:   fields?: Record<string, string>;
  21: }
  22: 
  23: export class ApiError extends Error {
  24:   readonly code: ApiErrorCode;
  25:   readonly status: number;
  26:   readonly detail?: string;
  27:   readonly fields?: Record<string, string>;
  28: 
  29:   constructor(
  30:     code: ApiErrorCode,
  31:     message: string,
  32:     options: {
  33:       status?: number;
  34:       detail?: string;
  35:       fields?: Record<string, string>;
  36:       cause?: unknown;
  37:     } = {}
  38:   ) {
  39:     super(message, { cause: options.cause });
  40:     this.name = 'ApiError';
  41:     this.code = code;
  42:     this.status = options.status ?? statusByCode[code];
  43:     this.detail = options.detail;
  44:     this.fields = options.fields;
  45:   }
  46: }
  47: 
  48: const statusByCode: Record<ApiErrorCode, number> = {
  49:   BAD_REQUEST: 400,
  50:   UNAUTHORIZED: 401,
  51:   FORBIDDEN: 403,
  52:   NOT_FOUND: 404,
  53:   CONFLICT: 409,
  54:   TOO_MANY_REQUESTS: 429,
  55:   VALIDATION_ERROR: 422,
  56:   INTERNAL_SERVER_ERROR: 500,
  57:   SERVICE_UNAVAILABLE: 503,
  58: };
  59: 
  60: export function isApiError(error: unknown): error is ApiError {
  61:   return error instanceof ApiError;
  62: }
  63: 
  64: export function toApiErrorBody(error: ApiError): ApiErrorBody {
  65:   return {
  66:     code: error.code,
  67:     message: error.message,
  68:     ...(error.detail ? { detail: error.detail } : {}),
  69:     ...(error.fields ? { fields: error.fields } : {}),
  70:   };
  71: }
  72: 
  73: export function jsonError(error: ApiError) {
  74:   return NextResponse.json(toApiErrorBody(error), { status: error.status });
  75: }
