  91: async function request<T>(
  92:   path: string,
  93:   init: RequestInit & { accessToken?: string } = {}
  94: ) {
  95:   const headers = new Headers(init.headers);
  96: 
  97:   if (init.body && !headers.has('Content-Type')) {
  98:     headers.set('Content-Type', 'application/json');
  99:   }
 100: 
 101:   if (init.accessToken) {
 102:     headers.set('Authorization', `Bearer ${init.accessToken}`);
 103:   }
 104: 
 105:   const response = await fetch(buildUrl(path), {
 106:     ...init,
 107:     headers,
 108:     credentials: 'include',
 109:   });
 110: 
 111:   if (!response.ok) {
 112:     let message = 'Request failed';
 113: 
 114:     try {
 115:       const errorBody = (await response.json()) as ErrorResponse;
 116:       message = errorBody.message || errorBody.detail || message;
 117:     } catch {}
 118: 
 119:     throw new Error(message);
 120:   }
 121: 
 122:   if (response.status === 204) {
 123:     return null as T;
 124:   }
 125: 
 126:   const body = (await response.json()) as SuccessResponse<T>;
 127:   return body.data;
 128: }
