 209: export async function exchangeOpenfortSession(input: OpenfortExchangeInput) {
 210:   const openfortSession = await verifyOpenfortAccessToken(input.accessToken);
 211:   const { user, created } = await findOrCreateUser(input, openfortSession);
 212: 
 213:   if (!created) {
 214:     await assertUserNotLocked(user.id);
 215:   }
 216: 
 217:   const refreshToken = createOpaqueToken();
 218:   const authConfig = getAuthConfig();
 219:   const now = Date.now();
 220:   const accessTokenExpiresAt = new Date(now + authConfig.accessTokenTtlMs);
 221:   const session = await createSession({
 222:     userId: user.id,
 223:     refreshTokenHash: hashOpaqueToken(refreshToken),
 224:     metadata: input.metadata,
 225:     activityTimeoutAt: new Date(now + authConfig.activityTimeoutMs),
 226:     absoluteExpiresAt: new Date(now + authConfig.absoluteSessionTtlMs),
 227:   });
 228:   const accessToken = await signAppAccessToken(
 229:     {
 230:       userId: user.id,
 231:       sessionId: session.id,
 232:       kycVerified: Boolean(user.kycVerified),
 233:       kybVerified: Boolean(user.kybVerified),
 234:       type: user.type,
 235:       role: user.role,
 236:     },
 237:     accessTokenExpiresAt
 238:   );
 239: 
 240:   return {
 241:     userId: user.id,
 242:     accessToken,
 243:     accessTokenExpiresAt,
 244:     refreshToken,
 245:     refreshTokenExpiresAt: new Date(now + authConfig.absoluteSessionTtlMs),
 246:   };
 247: }
