import 'server-only';

export const refreshTokenCookieName = 'refresh_token';

const defaultAccessTokenTtlMs = 15 * 60 * 1000;
const defaultActivityTimeoutMs = 15 * 60 * 1000;
const defaultAbsoluteSessionTtlMs = 7 * 24 * 60 * 60 * 1000;

function readOptionalString(name: string) {
  const value = process.env[name]?.trim();
  return value ? value : undefined;
}

function parseDuration(value: string | undefined, fallbackMs: number) {
  if (!value) return fallbackMs;

  const match = value.match(/^(\d+)(ms|s|m|h|d)?$/i);
  if (!match) return fallbackMs;

  const amount = Number(match[1]);
  const unit = match[2]?.toLowerCase() ?? 'ms';
  const multipliers: Record<string, number> = {
    ms: 1,
    s: 1000,
    m: 60 * 1000,
    h: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
  };

  return amount * multipliers[unit];
}

function readDuration(names: string[], fallbackMs: number) {
  for (const name of names) {
    const parsed = parseDuration(readOptionalString(name), fallbackMs);
    if (parsed !== fallbackMs || readOptionalString(name)) {
      return parsed;
    }
  }

  return fallbackMs;
}

export function getAuthConfig() {
  return {
    accessTokenTtlMs: readDuration(
      ['APP_JWT_ACCESS_TOKEN_TTL', 'INFRA_AUTH_JWT_ACCESS_TOKEN_TTL'],
      defaultAccessTokenTtlMs
    ),
    activityTimeoutMs: readDuration(
      ['APP_AUTH_SESSION_ACTIVITY_TIMEOUT', 'INFRA_AUTH_ACTIVITY_TIMEOUT'],
      defaultActivityTimeoutMs
    ),
    absoluteSessionTtlMs: readDuration(
      ['APP_AUTH_SESSION_ABSOLUTE_TTL', 'INFRA_AUTH_ABSOLUTE_EXPIRES_DURATION'],
      defaultAbsoluteSessionTtlMs
    ),
    cookieDomain:
      readOptionalString('APP_REFRESH_COOKIE_DOMAIN') ??
      readOptionalString('INFRA_REST_COOKIE_DOMAIN'),
    cookieSameSite: (
      readOptionalString('APP_REFRESH_COOKIE_SAME_SITE') ??
      readOptionalString('INFRA_REST_COOKIE_SAME_SITE') ??
      'lax'
    ).toLowerCase(),
  };
}

import 'server-only';

import { Prisma, type UserRole, type UserType } from '@prisma/client';

import { getDb } from '@/server/db';

export interface CreateUserRecord {
  openfortUserId: string;
  email?: string | null;
  firstName?: string | null;
  lastName?: string | null;
  phoneNumber?: string | null;
  companyName?: string | null;
  type: UserType;
  role: UserRole;
}

export type UserWithOrganization = Prisma.UserGetPayload<{
  include: { organization: true };
}>;

export function findActiveUserById(userId: string) {
  return getDb().user.findFirst({
    where: { id: userId, deletedAt: null },
    include: { organization: true },
  });
}

export function findUserByOpenfortId(openfortUserId: string) {
  return getDb().user.findFirst({
    where: {
      openfortUserId,
      deletedAt: null,
    },
  });
}

export async function openfortUserExists(openfortUserId: string) {
  const count = await getDb().user.count({
    where: {
      openfortUserId,
      deletedAt: null,
    },
  });

  return count > 0;
}

export async function createUser(record: CreateUserRecord) {
  return getDb().$transaction(async (tx) => {
    const user = await tx.user.create({
      data: {
        openfortUserId: record.openfortUserId,
        email: record.email,
        firstName: record.firstName,
        lastName: record.lastName,
        phoneNumber: record.phoneNumber,
        type: record.type,
        role: record.role,
        status: 'pending_kyc',
      },
    });

    if (record.type === 'organization' && record.companyName) {
      await tx.userOrganization.create({
        data: {
          userId: user.id,
          name: record.companyName,
        },
      });
    }

    return user;
  });
}

export async function softDeleteUserAccount(userId: string) {
  const db = getDb();
  const now = new Date();

  await db.$transaction(async (tx) => {
    const user = await tx.user.findFirst({
      where: { id: userId, deletedAt: null },
      select: { dataDeletionRequestedAt: true },
    });

    if (!user) return;

    await tx.session.updateMany({
      where: { userId, revokedAt: null },
      data: {
        revokedAt: now,
        revokedReason: 'user_terminated',
        revokedByUserId: null,
      },
    });

    await tx.user.update({
      where: { id: userId },
      data: {
        email: null,
        phoneNumber: null,
        openfortUserId: `deleted:${userId}`,
        dataDeletionRequestedAt: user.dataDeletionRequestedAt ?? now,
        deletedAt: now,
        updatedAt: now,
      },
    });
  });
}

export function isUserUniqueConstraintError(error: unknown) {
  return (
    error instanceof Prisma.PrismaClientKnownRequestError &&
    error.code === 'P2002'
  );
}

import 'server-only';

import { authenticateAppRequest } from '@/server/services/auth';
import { ApiError } from '@/server/http';
import {
  findActiveUserById,
  softDeleteUserAccount,
  type UserWithOrganization,
} from '@/server/repositories/users';
import { deleteOpenfortUser } from '@/server/openfort/session';
import { logger } from '@/server/logger';

async function getAuthenticatedUser(accessToken: string) {
  const { user: sessionUser } = await authenticateAppRequest(accessToken);
  const user = await findActiveUserById(sessionUser.id);

  if (!user) {
    throw new ApiError('UNAUTHORIZED', 'Invalid access token.');
  }

  return user;
}

function isOrganization(user: UserWithOrganization) {
  return user.type === 'organization';
}

function isKycPending(user: UserWithOrganization) {
  return !Boolean(user.kycVerified);
}

function isKybPending(user: UserWithOrganization) {
  return isOrganization(user) && !Boolean(user.kybVerified);
}

function serializeTimestamp(value: Date | null) {
  return value?.toISOString() ?? null;
}

export async function getCurrentUser(accessToken: string) {
  const user = await getAuthenticatedUser(accessToken);

  return {
    user_id: user.id,
    openfort_user_id: user.openfortUserId,
    email: user.email,
    first_name: user.firstName,
    last_name: user.lastName,
    company_name: user.organization?.name ?? null,
    phone_number: user.phoneNumber,
    type: user.type,
    role: user.role,
    status: user.status,
    kyc_verified: Boolean(user.kycVerified),
    kyb_verified: Boolean(user.kybVerified),
  };
}

export async function getAccountStatus(accessToken: string) {
  const user = await getAuthenticatedUser(accessToken);

  return {
    user_id: user.id,
    openfort_user_id: user.openfortUserId,
    type: user.type,
    role: user.role,
    status: user.status,
    kyc_verified: Boolean(user.kycVerified),
    kyb_verified: Boolean(user.kybVerified),
    pending_kyc: isKycPending(user),
    pending_kyb: isKybPending(user),
  };
}

export async function getKycStatus(accessToken: string) {
  const user = await getAuthenticatedUser(accessToken);

  return {
    user_id: user.id,
    status: user.status,
    type: user.type,
    kyc_verified: Boolean(user.kycVerified),
    kyc_verified_at: serializeTimestamp(user.kycVerifiedAt),
    kyb_verified: Boolean(user.kybVerified),
    kyb_verified_at: serializeTimestamp(user.kybVerifiedAt),
    pending_kyc: isKycPending(user),
    pending_kyb: isKybPending(user),
  };
}

export async function deleteCurrentAccount(accessToken: string) {
  const user = await getAuthenticatedUser(accessToken);
  const openfortUserId = user.openfortUserId;

  await softDeleteUserAccount(user.id);

  try {
    await deleteOpenfortUser(openfortUserId);
  } catch (error) {
    logger.warn(
      { err: error, userId: user.id, openfortUserId },
      'Failed to delete Openfort user after local account deletion'
    );
  }
}

